    validate_a_stored_mobile_session: {
        parameters: {
            query: {
                /** @description Workspace origin expected by the mobile cache namespace. */
                workspaceOrigin: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Mobile session is valid for the requested workspace. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        ok?: boolean;
                        data?: {
                            /** @description Canonical workspace origin bound to the validated mobile session. */
                            workspaceOrigin: string;
                            /** @description Stable workspace identifier safe for cache, draft, and restore namespace keys. */
                            workspaceId: string;
                            /** @description Resolved authenticated subject. */
                            subject: string;
                            /** @description Normalized role list safe to use for cache namespacing. */
                            roles: string[];
                            /** @description Optional expiry hint surfaced for UX only. */
                            expiresAt: string | null;
                            authentication: {
                                /**
                                 * @description Fixed mobile auth provider scope for v1.
                                 * @enum {string}
                                 */
                                provider: "local";
                                /**
                                 * @description Browser-only login transport reused by `/auth/login`.
                                 * @enum {string}
                                 */
                                browserLoginTransport: "cookie-session";
                                /**
                                 * @description Opaque bearer transport persisted by the mobile app.
                                 * @enum {string}
                                 */
                                mobileSessionTransport: "opaque-bearer";
                                /**
                                 * @description Stable mobile session kind returned by the standalone login exchange.
                                 * @enum {string}
                                 */
                                sessionKind: "local-mobile-session-v1";
                            };
                        };
                    };
                };
            };
            /** @description Missing or invalid workspaceOrigin query parameter. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Opaque mobile bearer token is missing, invalid, or expired. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Session belongs to a different workspace namespace. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
    create_a_mobile_opaque_bearer_session: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @description Workspace origin to bind to the created mobile session. */
                    workspaceOrigin: string;
                    /** @description Local username for direct mobile login. */
                    username?: string;
                    /** @description Local password for direct mobile login. */
                    password?: string;
                    /** @description One-time bootstrap token to redeem instead of sending credentials. */
                    bootstrapToken?: string;
                };
            };
        };
        responses: {
            /** @description Opaque mobile session created successfully. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        ok?: boolean;
                        data?: {
                            session?: {
                                /** @enum {string} */
                                kind: "local-mobile-session-v1";
                                /** @description Opaque bearer token stored by the mobile app. */
                                token: string;
                            };
                            status?: {
                                /** @description Canonical workspace origin bound to the validated mobile session. */
                                workspaceOrigin: string;
                                /** @description Stable workspace identifier safe for cache, draft, and restore namespace keys. */
                                workspaceId: string;
                                /** @description Resolved authenticated subject. */
                                subject: string;
                                /** @description Normalized role list safe to use for cache namespacing. */
                                roles: string[];
                                /** @description Optional expiry hint surfaced for UX only. */
                                expiresAt: string | null;
                                authentication: {
                                    /**
                                     * @description Fixed mobile auth provider scope for v1.
                                     * @enum {string}
                                     */
                                    provider: "local";
                                    /**
                                     * @description Browser-only login transport reused by `/auth/login`.
                                     * @enum {string}
                                     */
                                    browserLoginTransport: "cookie-session";
                                    /**
                                     * @description Opaque bearer transport persisted by the mobile app.
                                     * @enum {string}
                                     */
                                    mobileSessionTransport: "opaque-bearer";
                                    /**
                                     * @description Stable mobile session kind returned by the standalone login exchange.
                                     * @enum {string}
                                     */
                                    sessionKind: "local-mobile-session-v1";
                                };
                            };
                        };
                    };
                };
            };
            /** @description Invalid payload or missing required fields. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Invalid credentials or bootstrap token. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Bootstrap token or session is not valid for the requested workspace. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
